//! The gh#983 scale audit may not ship a point outside the declared box.
//!
//! `scale_audit_bound_active.nl` (regenerated by the `.py` beside it) is
//! `min 1e-3·((y−1)² − Σxᵢ)` over `xᵢ ∈ [0, 1]` with a cubic row that is
//! inactive at the optimum: `xᵢ = 1`, `f* = −3e-3` exactly, and that is also
//! the infimum of `f` over the box the model declares. Every `xᵢ` is
//! bound-active with a multiplier equal to the objective's largest gradient.
//!
//! The objective is small, so the audit re-solves it multiplied up by `~1e3`.
//! That multiplies the bound multipliers by the same factor and shrinks each
//! bound's slack `mu/z` below the `bound_relax_factor` widening, so before
//! the fix the promoted re-solve reported `xᵢ = 1 + 4.97e-9` and
//! `f = −3.0000000149e-3` — below `f*`, an objective no point inside the
//! declared bounds reaches — while the base attempt's point sat inside them.
//! The same mechanism shipped `ex1_320` `1.0e-8` and `trainf` `7.0e-8`
//! outside their boxes.
//!
//! Two arms, one per branch of the fix:
//!
//! * default options: the re-solve keeps the declared variable box (the rows
//!   are still widened as in the base attempt), still promotes, and its
//!   point is inside the box (`pounce verify` agrees);
//! * a caller-named `bound_relax_factor`: the re-solve keeps the caller's
//!   widening, lands outside the box, and the declared-box conjunct declines
//!   it — and the report then carries the *base* attempt's box measurement,
//!   not the discarded re-solve's (the certificate floor used to leave that
//!   field behind).

use std::path::{Path, PathBuf};
use std::process::Command;

const F_STAR: f64 = -3e-3;

fn fixture() -> PathBuf {
    let mut fx = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    fx.push("tests");
    fx.push("fixtures");
    fx.push("scale_audit_bound_active.nl");
    fx
}

struct Run {
    stdout: String,
    report: serde_json::Value,
    sol: PathBuf,
}

fn run(tag: &str, extra: &[&str]) -> Run {
    let dir = std::env::temp_dir().join(format!(
        "pounce_983_declared_box_{}_{tag}",
        std::process::id()
    ));
    std::fs::create_dir_all(&dir).expect("temp dir");
    let sol = dir.join("out.sol");
    let json = dir.join("out.json");
    let out = Command::new(env!("CARGO_BIN_EXE_pounce"))
        .arg(fixture())
        .arg(&sol)
        .arg("--no-options-file")
        .arg("--json-output")
        .arg(&json)
        .args(extra)
        .output()
        .expect("run pounce");
    let stdout = String::from_utf8_lossy(&out.stdout).into_owned();
    assert!(out.status.success(), "pounce failed:\n{stdout}");
    let report = serde_json::from_str(&std::fs::read_to_string(&json).expect("read json"))
        .expect("parse json");
    Run {
        stdout,
        report,
        sol,
    }
}

fn verify(sol: &Path) -> String {
    let out = Command::new(env!("CARGO_BIN_EXE_pounce"))
        .arg("verify")
        .arg(fixture())
        .arg(sol)
        .output()
        .expect("run pounce verify");
    String::from_utf8_lossy(&out.stdout).into_owned() + &String::from_utf8_lossy(&out.stderr)
}

/// The returned point is inside the declared box, by the report's own
/// measurement, by reading `x` directly, and by `pounce verify`.
fn assert_inside_declared_box(r: &Run) {
    let x: Vec<f64> = r.report["solution"]["x"]
        .as_array()
        .expect("solution.x")
        .iter()
        .map(|v| v.as_f64().expect("x entry"))
        .collect();
    assert_eq!(x.len(), 4, "{:?}", x);
    // `y` (bounds ±10) is first; the three controls follow.
    assert!((-10.0..=10.0).contains(&x[0]), "y = {}", x[0]);
    for (i, &xi) in x[1..].iter().enumerate() {
        assert!(
            (0.0..=1.0).contains(&xi),
            "x{} = {xi:.17e} is outside its declared bounds [0, 1]\n{}",
            i + 1,
            r.stdout
        );
    }
    let obj = r.report["solution"]["objective"]
        .as_f64()
        .expect("objective");
    assert!(
        obj >= F_STAR,
        "objective {obj:.12e} is below f* = {F_STAR:e}, the infimum over the declared box"
    );
    let box_viol = r.report["statistics"]["final_declared_box_viol"]
        .as_f64()
        .expect("final_declared_box_viol");
    assert_eq!(box_viol, 0.0, "{}", r.stdout);
    let v = verify(&r.sol);
    assert!(
        v.contains("max bound violation     : 0.000e0"),
        "pounce verify disagrees:\n{v}"
    );
}

#[test]
fn a_promoted_re_solve_is_inside_the_declared_box() {
    let r = run("default", &[]);
    assert!(
        r.stdout.contains("gh#983 scale audit: promoted"),
        "this fixture exists to reach a promoted re-solve:\n{}",
        r.stdout
    );
    assert_inside_declared_box(&r);
    // And it is still the better answer it was promoted for: within the
    // `bound_relax_factor`-free optimum's reach, closer to `f*` than the base
    // attempt's `-2.9999925e-3`.
    let obj = r.report["solution"]["objective"].as_f64().unwrap();
    assert!(obj - F_STAR < 1e-10, "objective {obj:.12e}");
}

#[test]
fn a_re_solve_that_leaves_the_declared_box_is_declined_and_reported_as_the_base() {
    // Naming the factor (here: its default value) keeps the widening in the
    // re-solve, which then lands `~5e-9` outside the box.
    let r = run("named_relax", &["bound_relax_factor=1e-8"]);
    assert!(
        r.stdout
            .contains("gh#983 scale audit: declined (the re-solve's point is"),
        "{}",
        r.stdout
    );
    assert!(
        r.stdout.contains("EXIT: Optimal Solution Found."),
        "{}",
        r.stdout
    );
    assert_inside_declared_box(&r);
    let warnings = r.report["statistics"]["warnings"].to_string();
    assert!(
        warnings.contains("outside the declared variable bounds"),
        "{warnings}"
    );
}

#[test]
fn audit_off_is_the_base_attempt() {
    let r = run("audit_off", &["solve_quality_audit=no"]);
    assert!(!r.stdout.contains("gh#983 scale audit"), "{}", r.stdout);
    assert_inside_declared_box(&r);
}
